const panel=(title,body,id='',note='',extra='')=>`<section class="panel" ${id?`id="${id}"`:''}><div class="panel-head"><h2>${uiIcon(/haber/i.test(title)?'news':/takip/i.test(title)?'layers':/fonlama|pozisyon/i.test(title)?'derivatives':/ısı|harita/i.test(title)?'heatmap':/ETF/i.test(title)?'etf':'chart')}${titleCase(title)}</h2>${extra}</div>${body}${note?`<div class="panel-note">${note}</div>`:''}</section>`;
const empty=text=>text===undefined?loading():`<div class="empty">${text}</div>`;
const table=(heads,rows)=>`<div class="scroll-table"><table><thead><tr>${heads.map(h=>`<th>${titleCase(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>{let i=0;return row.replace(/<td(\s[^>]*|)>/g,(_,attrs='')=>`<td${attrs} data-label="${esc(titleCase(heads[i++]||''))}">`);}).join('')}</tbody></table></div>`;
const stamp=r=>`Güncellendi · ${timeFormat(r.fetchedAt,{seconds:true})}${r.stale?' · Önbellek / bağlantı kesik':''}`;
async function api(path){const r=await fetch('/api/'+path);const j=await r.json();if(!r.ok||j.error&&!j.data)throw Error(j.error||'Kaynak erişilemiyor');return j;}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function fill(id,html,gen=generation){if(gen===generation&&$(id))$(id).innerHTML=html;}
function settleStat(target,ok){const box=target?.closest('[data-stat]');if(!box)return;box.classList.remove('stat-pending');box.classList.toggle('stat-unavailable',!ok);box.setAttribute('aria-busy','false');if(!ok){const foot=box.querySelector('.stat-foot');if(foot)foot.textContent='Veri Alınamadı · Yenile İle Tekrar Dene';}}
const recoveryTimers=new Map();
async function load(id,path,render,gen=generation){try{const r=await api(path);if(recoveryTimers.has(id)){clearTimeout(recoveryTimers.get(id));recoveryTimers.delete(id);}fill(id,render(r),gen);if(gen===generation)settleStat($(id),true);return r;}catch(e){if(gen!==generation)return;const metric=$(id)?.closest('[data-stat]');fill(id,metric?'—':empty(`<span class="muted">Veri alınamadı</span><br>${esc(e.message)}<br>Bağlantı otomatik yeniden denenecek.`),gen);settleStat($(id),false);if(!recoveryTimers.has(id))recoveryTimers.set(id,setTimeout(()=>{recoveryTimers.delete(id);if(gen!==generation||!$(id))return;if($(id).closest('[data-stat]'))getStats(gen);else load(id,path,render,gen);},30000));}}

function coinRow(t){const s=t.symbol.replace('USDT','');return `<tr class="row-click" data-symbol="${esc(t.symbol)}"><td><button class="watch-star" data-watch="${t.symbol}" aria-label="${s} takip listesi">${watch.includes(t.symbol)?'★':'☆'}</button><b>${s}</b> <span class="muted"> - USDT</span></td><td>${money(t.lastPrice)}</td><td class="market-change ${changeClass(t.priceChangePercent)}">${pct(t.priceChangePercent)}</td><td>${short(t.quoteVolume)}</td></tr>`;}
function watchHtml(){return watchlists.html();}
function renderWatch(){const body=$('#watch-body');if(!body)return;const top=body.scrollTop;body.innerHTML=watchHtml();body.scrollTop=top;}

function heatHtml(){const list=coins.length?coins.filter(x=>(!tickers.length||tickerIndex.has(x.symbol.toUpperCase()+'USDT'))&&!['usdt','usdc','dai','usds','usde','susde','pyusd','rlusd','fdusd','usdd'].includes(x.symbol)).slice(0,18).map(x=>({symbol:x.symbol.toUpperCase()+'USDT',change:x.price_change_percentage_24h,weight:x.market_cap})):tickers.filter(x=>x.symbol.endsWith('USDT')&&!/UPUSDT|DOWNUSDT/.test(x.symbol)).sort((a,b)=>+b.quoteVolume-+a.quoteVolume).slice(0,18).map(x=>({symbol:x.symbol,change:+x.priceChangePercent,weight:+x.quoteVolume}));if(!list.length)return empty();return `<div class="heatmap">${list.map(x=>`<button class="heat-cell ${x.change<0?'negative':''}" data-symbol="${x.symbol}" style="flex-grow:${Math.max(1,Math.sqrt(x.weight/list.at(-1).weight))}"><b>${x.symbol.replace('USDT','')}</b><span>${pct(x.change)}</span></button>`).join('')}</div>`;}
async function loadSources(gen=generation){
 if(!$('#sources-body'))return;
 try{const r=await api('status');fill('#sources-body',Object.entries(r.data.sources).map(([key,v])=>`<div class="source-row"><div>${esc(key)}<small>Son Kontrol: ${dateTimeFormat(v.at,{seconds:true})}${v.lastSuccess&&!v.ok?' · Son Başarılı: '+dateTimeFormat(v.lastSuccess):''}${v.error?' · '+esc(v.error):''}</small></div><div class="source-state"><span class="${v.ok?'up':v.retrying?'muted':'down'}">${v.retrying?'● Yeniden Deneniyor':v.ok?'● Erişilebilir':'● Erişilemiyor'}</span>${!v.ok&&v.nextRetry&&!v.retrying?`<small>Sonraki Deneme: ${timeFormat(v.nextRetry)}</small>`:''}</div></div>`).join('')+`<div class="source-row"><div>Canlı İşlem Akışı<small>${esc(formatPair(selected))}</small></div><span class="${streamInfo.state==='live'?'up':'muted'}">${streamInfo.state==='live'?'● Canlı':'● Yeniden Bağlanıyor'}</span></div>`,gen);}catch{fill('#sources-body',empty('Bağlantı Durumları Alınamadı. Otomatik Yeniden Denenecek.'),gen);}
}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-retry-sources]');if(!button)return;button.disabled=true;try{const r=await fetch('/api/retry-failed',{method:'POST'});if(!r.ok)throw Error();toast('Başarısız Kaynaklar Yeniden Deneniyor');loadSources();}catch{toast('Yeniden Deneme Başlatılamadı');}finally{setTimeout(()=>{if(button.isConnected)button.disabled=false;},5000);}});
setInterval(()=>{if(route==='sources')loadSources();},10000);
function safeNewsURL(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:'#news';}catch{return '#news';}}
function newsHtml(r,limit=8){return r.data.items.slice(0,limit).map(x=>`<a class="news-item" href="${esc(safeNewsURL(x.url))}" target="_blank" rel="noreferrer"><div class="news-meta"><span>${newsImportance(x.title)}</span><span>${dateTimeFormat(x.date,{month:'short',year:false})} ↗</span></div>${newsHeadlines(x)}</a>`).join('');}
function statsHtml(){return `<div class="stats" aria-label="Piyasa Özeti"><div class="stat stat-pending" data-stat="btc" aria-busy="true"><div class="stat-label"><span class="coin-icon">₿</span> Bitcoin</div>${loading('Veriler Yükleniyor',{compact:true})}<div class="stat-value" id="btc-price">—</div><div class="stat-foot" id="btc-change">Canlı Veri Bekleniyor</div><div class="metric-line"><i></i></div></div><div class="stat stat-pending" data-stat="global" aria-busy="true"><div class="stat-label">${uiIcon('markets')} Toplam Piyasa Değeri</div>${loading('Veriler Yükleniyor',{compact:true})}<div class="stat-value" id="global-cap">—</div><div class="stat-foot" id="global-dom">Küresel Piyasa Özeti</div><div class="metric-line"><i></i></div></div><div class="stat stat-pending" data-stat="fear" data-sentiment="unavailable" aria-busy="true"><div class="stat-label">${uiIcon('gauge')} Korku Ve Açgözlülük</div>${loading('Veriler Yükleniyor',{compact:true})}<div class="stat-value sentiment-value"><span class="metric-number" id="fear-value">— <small>/ 100</small></span><span class="sentiment-badge" id="fear-zone">—</span></div><div class="stat-foot" id="fear-label">Günlük Piyasa Duyarlılığı</div><div class="metric-line" id="fear-gauge"><i></i></div></div><div class="stat stat-pending" data-stat="season" aria-busy="true"><div class="stat-label">${uiIcon('cycle')} Altcoin Sezonu</div>${loading('Veriler Yükleniyor',{compact:true})}<div class="stat-value"><span class="metric-number" id="season-value">— <small>/ 100</small></span><span class="season-badge" id="season-zone">Nötr</span></div><div class="stat-foot" id="season-label">90 Günlük Piyasa Genişliği</div><div class="season-track" id="season-meter" role="img" aria-label="Altcoin Sezonu Göstergesi">${Array.from({length:20},()=>'<span></span>').join('')}</div></div></div>`;}
function chartHtml(){return panel('Piyasa Terminali',`<div class="clarity-chart-controls"><button class="symbol-picker-button" id="symbol-picker" type="button" aria-haspopup="dialog" aria-label="Piyasa Seç"><strong id="selected-pair">${indexInstrument(selected)?.code||formatPair(selected)}</strong><span>⌕ Tüm Piyasalar</span></button><div class="chart-actions"><span class="chart-price-chip"><small>Anlık</small><strong id="chart-price">—</strong></span><button type="button" id="chart-fullscreen" aria-label="Grafiği Tam Ekran Aç" title="Tam Ekran">⛶</button></div></div>${terminalContextHtml()}<div id="chart" class="tv-chart-shell"></div>`,'','','<span class="tag" id="chart-live-tag">Canlı Grafik</span>').replace('<section class="panel"','<section class="panel chart-panel"');}

const tools=[['Likidite Ve Tasfiyeler','Emir Yoğunluğu · Tasfiye Akışı','liquidity-map','♨'],['Funding oranları','Sürekli vadeli fonlama','derivatives','ϟ'],['Açık pozisyon · 4s','OI ve pozisyon değişimi','derivatives','▥'],['Balina izleyici','Hyperliquid cüzdan pozisyonları','whale','⬡'],['RSI ısı haritası','Aşırı alım / aşırı satım','rsi','▦'],['Bitcoin ETF','Kurumsal günlük net akışlar','etf','▤'],['Long / short','Hesap oranı ve alım/satım','derivatives','⇄'],['Korku & açgözlülük','30 günlük duygu endeksi','fear','◷']];
function toolsHtml(list=tools){return list.map(([name,sub,id,icon])=>`<button class="tool" data-route="${id}"><span>${toolIcon(id)}</span><div><b>${titleCase(name)}</b><small>${titleCase(sub)}</small></div><em>↗</em></button>`).join('');}
async function getStats(gen){await Promise.allSettled([load('#global-cap','global',r=>'$'+short(r.data.total_market_cap.usd),gen).then(r=>{if(r&&gen===generation)$('#global-dom').innerHTML=`BTC Hakimiyeti ${num(r.data.market_cap_percentage.btc)}% · <span class="${cls(r.data.market_cap_change_percentage_24h_usd)}">${pct(r.data.market_cap_change_percentage_24h_usd)}</span>`;}),load('#fear-value','fear',r=>`${r.data.data[0].value} <small>/ 100</small>`,gen).then(r=>{if(r&&gen===generation){const f=r.data.data[0];$('#fear-gauge').style.setProperty('--value',f.value+'%');const sentiment=fearState(f.value);$('#fear-value').closest('[data-stat]').dataset.sentiment=sentiment.zone;$('#fear-zone').textContent=sentiment.label;$('#fear-label').textContent=dateFormat(+f.timestamp*1000);}}),load('#season-value','season',r=>`${r.data.index} <small>/ 100</small>`,gen).then(r=>{if(!r||gen!==generation)return;const d=r.data;$('#season-meter').setAttribute('aria-label',`Altcoin Sezonu ${d.index} / 100`);$('#season-meter').querySelectorAll('span').forEach((el,i)=>el.classList.toggle('active',i<Math.round(d.index/5)));$('#season-zone').textContent=d.index>=75?'Altcoin':d.index<=25?'Bitcoin':'Nötr';$('#season-label').textContent=`${d.winners} / ${d.count} Coin · 90 Gün`;}),load('#heat-body','coins',r=>{coins=r.data.coins;return heatHtml();},gen)]);updatePrices();}
async function drawChart(){chartVersion++;chart?.remove();chart=null;candleSeries=null;volumeSeries=null;smaSeries=null;chartReady=true;pendingTrades=[];if(!$('#chart'))return;chart=mountTradingView($('#chart'),{symbol:selected,interval,allowSymbolChange:false,preserve:true,onInterval:value=>{interval=value;localStorage.setItem('clarity.interval',value);setChartInterval(value);}});syncInstrumentUI();mountTerminalContext({symbol:selected,interval,api});}
function syncInstrumentUI(){const x=indexInstrument(selected);const chip=$('.chart-price-chip');if(chip)chip.hidden=!!x;if($('#chart-live-tag'))$('#chart-live-tag').textContent=x?'Endeks Grafiği':'Canlı Grafik';let note=$('#instrument-note');if(!note&&$('#chart')){note=document.createElement('div');note.id='instrument-note';note.className='panel-note instrument-note';$('#chart').after(note);}if(note){note.hidden=!x;note.textContent=x?`${x.name} · ${x.description} Değer ${x.kind==='dominance'?'yüzde (%)':'USD'} olarak grafiğin sağ ölçeğinde gösterilir.`:'';}for(const id of ['#book-body','#book-bids','#book-asks','#book-largest','#trade-body']){const panel=$(id)?.closest('.panel');if(panel)panel.dataset.indexView=String(!!x);}if(x){for(const id of ['#book-body','#book-bids','#book-asks','#book-largest'])if($(id))$(id).innerHTML=empty('Bu bir piyasa endeksidir; emir defteri bulunmaz.');if($('#trade-body'))$('#trade-body').innerHTML=empty('Bu bir hesaplanan endekstir; borsa işlem akışı bulunmaz.');}}
let currentSource='Binance';let previousRoute='';

function connectStream(){stream?.close();lastTrade=0;tradeIds.clear();trades=[];cvd=0;book=null;currentSource='Binance';stream=new EventSource('/api/stream?symbol='+streamSymbol(selected));stream.addEventListener('status',e=>{streamInfo=JSON.parse(e.data);if(isIndex(selected)){$('#connection').textContent='Endeks · '+indexInstrument(selected).code;$('#led').classList.remove('live');return;}if(streamInfo.state!=='live'){book=null;for(const id of ['#book-body','#book-bids','#book-asks','#book-largest'])if($(id))$(id).innerHTML=loading('Emir Defterine Bağlanılıyor');}$('#connection').textContent=streamInfo.state==='live'?`Canlı · ${formatPair(selected)}`:`İşlem akışı · bağlanıyor`;$('#led').classList.toggle('live',streamInfo.state==='live');if($('#chart-live-tag'))$('#chart-live-tag').textContent=streamInfo.state==='live'?'Canlı Grafik':'Bağlanıyor';});stream.addEventListener('tickers',e=>{for(const t of JSON.parse(e.data)){const item=tickerIndex.get(t.symbol);if(item){item.lastPrice=t.price;item.priceChangePercent=t.change;item.quoteVolume=t.volume;}}updatePrices();if($('#market-table'))renderMarket();});stream.addEventListener('trade',e=>{const t=JSON.parse(e.data);if(isIndex(selected)){checkAlerts('BTCUSDT',t.price);return;}const id=t.source+':'+t.id;if(tradeIds.has(id))return;tradeIds.add(id);if(tradeIds.size>20000)tradeIds.delete(tradeIds.values().next().value);if(t.source!==currentSource){currentSource=t.source;chartVersion++;chartReady=true;chartData=[];pendingTrades=[];candleSeries?.setData([]);volumeSeries?.setData([]);smaSeries?.setData([]);trades=[];cvd=0;toast('Yedek piyasa akışına geçildi. Mumlar bu akıştan oluşturuluyor.');}lastTrade=Date.now();trades.unshift(t);trades=trades.slice(0,60);cvd+=(t.side==='buy'?1:-1)*t.qty;const tick=tickers.find(x=>x.symbol===selected);if(tick)tick.lastPrice=t.price;updatePrices(t);checkAlerts(selected,t.price);if($('#trade-body'))$('#trade-body').innerHTML=trades.slice(0,route==='terminal'?10:22).map(x=>`<div class="trade-row"><span class="${x.side==='buy'?'up':'down'}">${num(x.price)}</span><span>${num(x.qty,5)}</span><span class="muted">${timeFormat(x.time,{seconds:true})}</span></div>`).join('');if($('#cvd'))$('#cvd').textContent=`CVD ${num(cvd,3)} · canlı`;});stream.addEventListener('book',e=>{if(isIndex(selected))return;book=JSON.parse(e.data);renderBook();});stream.onerror=()=>{if(isIndex(selected))return;$('#led').classList.remove('live');$('#connection').textContent='Bağlantı kesildi · tekrar deneniyor';};}
function renderBook(){if(!book||!['#book-body','#book-bids','#book-asks','#book-largest'].some(id=>$(id)))return;const rows=(list,side)=>{const max=Math.max(...list.slice(0,10).map(x=>+x[1]));return list.slice(0,10).map(x=>`<div class="depth-row ${side}" style="--width:${+x[1]/max*100}%"><span class="${side==='sell'?'down':'up'}">${num(x[0])}</span><span>${num(x[1],5)}</span><span class="muted">${short(x[0]*x[1])}</span></div>`).join('');};if($('#book-body'))$('#book-body').innerHTML=rows(book.asks,'sell')+`<div class="panel-note">Fiyat / miktar / değer</div>`+rows(book.bids,'buy');if($('#book-bids'))$('#book-bids').innerHTML=rows(book.bids,'buy');if($('#book-asks'))$('#book-asks').innerHTML=rows(book.asks,'sell');
 if($('#book-largest')){const levels=largestBookLevels(book),max=Math.max(...levels.map(x=>x.value),1);$('#book-largest').innerHTML=levels.length?levels.map(x=>`<div class="depth-row large-order-row ${x.side}" style="--width:${x.value/max*100}%"><span class="${x.side==='buy'?'up':'down'}"><i class="book-side">${x.side==='buy'?'Alış':'Satış'}</i>${num(x.price)}</span><span>${num(x.qty,5)}</span><span class="large-order-value">${short(x.value)}</span></div>`).join(''):empty('Bekleyen emir verisi yok.');const scope=$('#large-orders-scope');if(scope)scope.textContent=`${book.bids?.length||0} alış / ${book.asks?.length||0} satış seviyesi içinden, her yöndeki en büyük 5 seviye. Aynı fiyattaki emirlerin toplamıdır.`;}
}
